using System;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public sealed class SettingsView:MonoBehaviour
 {
  GameRuntime game;string language="";bool resetConfirmation;public void Initialize(GameRuntime runtime){game=runtime;Build();}
  void Update(){if(game!=null&&language!=game.State.Settings.language)Build();}
  string T(string key)=>SettingsRules.Text(game.State.Settings.language,"ui:"+key);
  void Build(){language=game.State.Settings.language;WorkshopUIFactory.Clear(transform);WorkshopUIFactory.Label("SettingsTitle",transform,T("settings"),18,44);WorkshopUIFactory.Label("LanguageTitle",transform,T("language"),16,40);for(int i=0;i<SettingsCatalog.Languages.Length;i++){string code=SettingsCatalog.Languages[i];WorkshopUIFactory.Button("Language-"+code,transform,SettingsCatalog.LanguageNames[i]+(language==code?" ✓":""),()=>game.Act(s=>SettingsRules.Change(s,"language",code)));}foreach(string mode in new[]{"1","10","max"}){string value=mode;WorkshopUIFactory.Button("BuyMode-"+value,transform,"×"+value,()=>game.Act(s=>SettingsRules.Change(s,"buy-mode",value)));}WorkshopUIFactory.Label("NumberFormatTitle",transform,T("numberFormat"),16,44);foreach(string format in new[]{"auto","scientific","engineering"}){string value=format;WorkshopUIFactory.Button("NumberFormat-"+value,transform,value,()=>game.Act(s=>SettingsRules.Change(s,"number-format",value)));}foreach(string action in new[]{"toggle-effects","toggle-haptics","toggle-music","toggle-sfx"}){string id=action;string key=id=="toggle-effects"?"animations":id=="toggle-haptics"?"haptics":id=="toggle-music"?"music":"muteEffects";var button=WorkshopUIFactory.Button("Setting-"+id,transform,T(key),()=>{game.Act(s=>SettingsRules.Change(s,id));Build();});button.GetComponentInChildren<Text>().text+=" · "+(id=="toggle-effects"?game.State.Settings.effects:id=="toggle-haptics"?game.State.Settings.hapticsEnabled:id=="toggle-music"?game.State.Settings.musicEnabled:game.State.Settings.sfxMuted);}Volume("music-volume",T("musicVolume"),game.State.Settings.musicVolume);Volume("sfx-volume",T("effectsVolume"),game.State.Settings.sfxVolume);WorkshopUIFactory.Button("SettingsSoundTest",transform,T("testSound"),()=>{game.Audio.Unlock();game.Audio.Play("unlock");});WorkshopUIFactory.Label("HapticsAvailability",transform,language=="de"?"Haptik: keine vorhandene Unity-Patternanbindung auf dieser Plattform. Einstellung bleibt gespeichert.":"Haptics: no existing Unity pattern bridge on this platform. Preference is saved.",14,80);ResetUI();}
  void ResetUI(){WorkshopUIFactory.Button("SaveToolsFromSettings",transform,T("exportSave")+" / Recovery",()=>game.UserShow("storage"));var b=WorkshopUIFactory.Button("RequestCampaignReset",transform,"Reset saved game",()=>{resetConfirmation=true;Build();});b.interactable=game.Writable&&!ChallengeRules.Active(game.State);if(!resetConfirmation)return;WorkshopUIFactory.Label("CampaignResetWarning",transform,"All progress will reset. A complete original copy is preserved locally before replacement.",14,110);WorkshopUIFactory.Button("CancelCampaignReset",transform,"Cancel",()=>{resetConfirmation=false;Build();});var confirm=WorkshopUIFactory.Button("ConfirmCampaignReset",transform,"Confirm new campaign",()=>{resetConfirmation=false;game.StartNewCampaign();});confirm.interactable=game.Writable&&!ChallengeRules.Active(game.State);}
  void Volume(string action,string title,double current){WorkshopUIFactory.Label("Volume-"+action,transform,title+" · "+Math.Round(current*100)+" %",14,44);var row=WorkshopUIFactory.Horizontal("VolumeButtons-"+action,transform).transform;WorkshopUIFactory.Button(action+"-minus",row,"−",()=>{game.Act(s=>SettingsRules.Change(s,action,amount:(action=="music-volume"?s.Settings.musicVolume:s.Settings.sfxVolume)-.01));Build();});WorkshopUIFactory.Button(action+"-plus",row,"+",()=>{game.Act(s=>SettingsRules.Change(s,action,amount:(action=="music-volume"?s.Settings.musicVolume:s.Settings.sfxVolume)+.01));Build();});}
 }
}
